INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 38, 'theory', 'Quiz: components and the router');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 38, 0, 'Which way do data and events flow in a component tree?', '["Data up, events down", "Data down through props, events up through handlers", "Everything through global variables", "Only inside a single component"]', 1, 'One-way flow: the parent passes props, and the child reports events by calling the functions it was given.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 38, 1, 'Where should you keep state needed by two sibling components?', '["In a global variable", "In the nearest common ancestor", "In each component separately", "In localStorage"]', 1, 'State is lifted to the nearest common ancestor, and a value and change functions are passed down.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 38, 2, 'What is history.pushState for?', '["It reloads the page", "It changes the address in the browser bar without a reload and adds a history entry", "It clears the history", "It sends a request to the server"]', 1, 'pushState adds an entry and replaceState replaces the current one; Back and Forward fire popstate.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 38, 3, 'Which clicks should a Link component intercept?', '["All clicks on any link", "A plain left click without modifiers on a same-origin link without target=_blank", "Only right clicks", "Only clicks with Ctrl"]', 1, 'A middle click and clicks with modifiers are for "open in a new tab", so they are left to the browser.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 38, 4, 'Why do you need an error boundary?', '["To speed up rendering", "So that an exception while rendering part of the UI shows a fallback instead of crashing the whole app", "To hide server errors", "For type checking"]', 1, 'The boundary catches errors from child components and shows a fallback with the option to retry.');
